export const createCustomerInvoice = defineFunction({
  name: "pennylane.create_customer_invoice",
  connector: "pennylane",
  class: "write",
  description: "Create a customer invoice as a draft (draft must be true). The customer must exist (list_customers, create_customer). Finalizing and sending are separate functions, called only after explicit human validation. Each line takes exactly one of two shapes, with no other key (any deviation is refused as NotAnyOf): a product line {product_id, quantity}, the product filling the rest (label, raw_currency_unit_price, unit, vat_rate may override it); or a free line {label, quantity, unit, raw_currency_unit_price, vat_rate}, all required. raw_currency_unit_price is the unit price before tax as a string (\"700.00\"); quantity is a number, never a string. Pass an external_reference to trace the source and look it up before creating again.",
  schema: z.strictObject({
    "customer_id": z.int().gte(1),
    "date": z.string().meta({"description": "YYYY-MM-DD.", "format": "date"}),
    "deadline": z.string().meta({"description": "Payment deadline, YYYY-MM-DD.", "format": "date"}),
    "invoice_lines": z.array(z.union([z.strictObject({
    "product_id": z.int().gte(1),
    "quantity": z.number(),
    "label": z.string().optional(),
    "raw_currency_unit_price": z.string().regex(new RegExp("^-?[0-9]+(\\.[0-9]+)?$")).describe("Decimal amount as a string, e.g. \"700.00\".").optional(),
    "unit": z.string().optional(),
    "vat_rate": z.string().regex(new RegExp("^[A-Za-z0-9_]+$")).describe("Pennylane VAT code, never a percentage: FR_200 (20%), FR_100 (10%), FR_55 (5.5%), FR_21 (2.1%), exempt. Reverse-charge codes: intracom_21, intracom_55, intracom_85, intracom_100, extracom, crossborder, FR_85_construction, FR_100_construction, FR_200_construction.").optional(),
    "description": z.string().optional(),
  }), z.strictObject({
    "label": z.string().min(1),
    "quantity": z.number(),
    "unit": z.string(),
    "raw_currency_unit_price": z.string().regex(new RegExp("^-?[0-9]+(\\.[0-9]+)?$")).describe("Decimal amount as a string, e.g. \"700.00\"."),
    "vat_rate": z.string().regex(new RegExp("^[A-Za-z0-9_]+$")).describe("Pennylane VAT code, never a percentage: FR_200 (20%), FR_100 (10%), FR_55 (5.5%), FR_21 (2.1%), exempt. Reverse-charge codes: intracom_21, intracom_55, intracom_85, intracom_100, extracom, crossborder, FR_85_construction, FR_100_construction, FR_200_construction."),
    "description": z.string().optional(),
  })])).min(1),
    "draft": z.literal(true).describe("Always true: the invoice is created as a draft."),
    "external_reference": z.string().describe("Trace of the source, unique; look it up before creating again.").optional(),
    "pdf_invoice_free_text": z.string().describe("Free text printed on the PDF, visible to the customer.").optional(),
    "pdf_invoice_subject": z.string().describe("Title printed on the PDF.").optional(),
    "customer_invoice_template_id": z.int().gte(1).describe("Rendering template, from list_invoice_templates.").optional(),
    "label": z.string().describe("Label of the accounting entry; generated when absent.").optional(),
    "currency": z.string().regex(new RegExp("^[A-Z]{3}$")).describe("ISO 4217, EUR by default.").optional(),
    "language": z.enum(["fr_FR", "en_GB", "de_DE", "es_ES"]).optional(),
  }),
  examples: [
    { title: "A draft invoice with one product line", input: {"customer_id": 3001, "date": "2026-10-06", "deadline": "2026-11-05", "draft": true, "invoice_lines": [{"product_id": 1201, "quantity": 3}]} },
    { title: "A draft invoice with one free line", input: {"customer_id": 3001, "date": "2026-10-06", "deadline": "2026-11-05", "draft": true, "invoice_lines": [{"label": "Workshop", "quantity": 1, "unit": "day", "raw_currency_unit_price": "1200.00", "vat_rate": "FR_200"}]} },
  ],
  refusals: [],
  request: {
    method: "POST",
    path: "/customer_invoices",
    pathParams: [],
    query: {},
    body: {"customer_id": "customer_id", "date": "date", "deadline": "deadline", "invoice_lines": "invoice_lines", "draft": "draft", "external_reference": "external_reference", "pdf_invoice_free_text": "pdf_invoice_free_text", "pdf_invoice_subject": "pdf_invoice_subject", "customer_invoice_template_id": "customer_invoice_template_id", "label": "label", "currency": "currency", "language": "language"},
    headers: {},
  },
  cost: { per: "request" },
})

