export const createLedgerEntry = defineFunction({
  name: "pennylane.create_ledger_entry",
  connector: "pennylane",
  class: "sensitive",
  description: "Post an entry to the general ledger. Pennylane has no draft for a ledger entry and the API cannot delete one: the entry is posted at once, and the only remedy is update_ledger_entry. Before calling, give the user the exact detail (journal, date, label, each line with its account and amount) and wait for agreement. Each line carries debit and credit as decimal strings (\"120.50\", \"0.00\") and a ledger_account_id (list_ledger_accounts); total debits must equal total credits, or Pennylane refuses the entry. journal_id comes from list_journals. 1 to 1000 lines. The order of the returned lines is not guaranteed: find a line by its content.",
  schema: z.strictObject({
    "date": z.string().meta({"description": "YYYY-MM-DD.", "format": "date"}),
    "label": z.string().min(1),
    "journal_id": z.int().gte(1),
    "ledger_entry_lines": z.array(z.strictObject({
    "debit": z.string().regex(new RegExp("^-?[0-9]+(\\.[0-9]+)?$")).describe("Decimal amount as a string, e.g. \"700.00\"."),
    "credit": z.string().regex(new RegExp("^-?[0-9]+(\\.[0-9]+)?$")).describe("Decimal amount as a string, e.g. \"700.00\"."),
    "ledger_account_id": z.int().gte(1),
    "label": z.string().optional(),
  })).min(1).max(1000),
    "due_date": z.string().meta({"description": "YYYY-MM-DD.", "format": "date"}).optional(),
    "currency": z.string().regex(new RegExp("^[A-Z]{3}$")).describe("ISO 4217, EUR by default.").optional(),
    "piece_number": z.string().describe("Generated when absent.").optional(),
  }),
  examples: [
    { title: "A balanced two-line entry", input: {"date": "2026-10-06", "label": "Bank fees October", "journal_id": 12, "ledger_entry_lines": [{"debit": "15.00", "credit": "0.00", "ledger_account_id": 4101}, {"debit": "0.00", "credit": "15.00", "ledger_account_id": 4102}]} },
  ],
  refusals: [
    { code: "entry_unbalanced", when: "total debits differ from total credits", message: "The entry is not balanced: total debits must equal total credits." },
  ],
  request: {
    method: "POST",
    path: "/ledger_entries",
    pathParams: [],
    query: {},
    body: {"date": "date", "label": "label", "journal_id": "journal_id", "ledger_entry_lines": "ledger_entry_lines", "due_date": "due_date", "currency": "currency", "piece_number": "piece_number"},
    headers: {},
  },
  cost: { per: "request" },
  confirm: { summary: "Post ledger entry \"{label}\" dated {date} in journal {journal_id}: no draft, and the API cannot delete it." },
})

export const letterLedgerEntryLines = defineFunction({
  name: "pennylane.letter_ledger_entry_lines",
  connector: "pennylane",
  class: "sensitive",
  description: "Letter ledger entry lines together. Not to be confused with matching a bank transaction to an invoice (match_customer_invoice_transaction, match_supplier_invoice_transaction): the wrong one raises no error, it just acts on the wrong objects. Lettering spreads: if a line passed is already lettered, the lettering extends to the lines it is already lettered with (asking for A and C when A and B are lettered gives A, B and C); check the result with list_lettered_lines. Pass line ids, not entry ids (list_ledger_entry_lines). unbalanced_lettering_strategy none refuses an unbalanced lettering, partial accepts it.",
  schema: z.strictObject({
    "ledger_entry_lines": z.array(z.strictObject({
    "id": z.int().gte(1),
  })).min(2).describe("At least two ledger entry lines, as {id}."),
    "unbalanced_lettering_strategy": z.enum(["none", "partial"]).meta({"description": "none refuses an unbalanced lettering; partial accepts it.", "default": "none"}),
  }),
  examples: [
    { title: "Letter an invoice line with its payment line", input: {"ledger_entry_lines": [{"id": 20001}, {"id": 20002}], "unbalanced_lettering_strategy": "none"} },
  ],
  refusals: [],
  request: {
    method: "POST",
    path: "/ledger_entry_lines/lettering",
    pathParams: [],
    query: {},
    body: {"ledger_entry_lines": "ledger_entry_lines", "unbalanced_lettering_strategy": "unbalanced_lettering_strategy"},
    headers: {},
  },
  cost: { per: "request" },
  confirm: { summary: "Letter the given ledger entry lines together; lines already lettered bring their group along." },
})

